import json,sympy as s
from pathlib import Path
R=Path(__file__).resolve().parents[1];E=[];checks=[]
x,y,z,r,t,p=s.symbols('x y z r theta phi',real=True)
def pair(a,b=None):return {'ko':a,'en':a if b is None else b}
def add(n,ko,en,steps,ans,check=None,parts=[]):
 E.append({'id':f'stewart9-review-15-{n}','number':n,'subparts':parts,'topic':pair('15장 복습','Chapter 15 Review'),'statement':pair(ko,en),'hint':pair('영역과 미분요소를 먼저 적고, 적분 순서 또는 좌표계를 선택한다.','Describe the region and differential element before choosing the integration order or coordinates.'),'steps':{'ko':[v[0] for v in steps],'en':[v[1] for v in steps]},'answer':pair(ans),'check':pair(*(check or ('경계와 미분요소를 대조하고 별도 계산으로 검산했다.','The bounds and differential element were checked and the calculation was independently verified.'))),'status':'math-verified','source':{'printedPage':1156 if n<=13 else 1157 if n<=46 else 1158,'pdfPage':1193 if n<=13 else 1194 if n<=46 else 1195},'conceptHref':'../s15-9.html'})
def calc(n,expr,lims,description=None,setup=None):
 I=expr; stages=[]
 for lim in lims:
  old=I;I=s.simplify(s.integrate(I,lim));stages.append((fr'\({s.latex(lim[0])}\)에 대해 적분한다: \[\int_{{{s.latex(lim[1])}}}^{{{s.latex(lim[2])}}}({s.latex(old)})\,d{s.latex(lim[0])}={s.latex(I)}.\]',fr'Integrate with respect to \({s.latex(lim[0])}\): \[\int_{{{s.latex(lim[1])}}}^{{{s.latex(lim[2])}}}({s.latex(old)})\,d{s.latex(lim[0])}={s.latex(I)}.\]'))
 full=s.latex(s.Integral(expr,*lims))
 ko,en=description or (fr'반복적분 \({full}\)을 계산하라.',fr'Evaluate the iterated integral \({full}\).')
 if setup:stages.insert(0,setup)
 add(n,ko,en,stages,fr'\[{s.latex(I)}.\]');checks.append({'number':n,'integral':str(s.Integral(expr,*lims)),'value':str(I)})
