add(9,r'上半平面の半円環 \(4\le x^2+y^2\le16,\ y\ge0\)上の \(\iint_R f\,dA\) を反復積分で表せ。'.replace('上半平面の半円環','상반평면의 반원 고리').replace('上の','에서').replace('を反復積分で表せ。','를 반복적분으로 나타내라.'),r'Write the integral of a continuous \(f\) over \(4\le x^2+y^2\le16,\ y\ge0\) in iterated form.',[(r'반지름은 2부터 4, 각은 0부터 π이다. 극좌표의 면적요소는 \(r\,dr\,d\theta\)이다.',r'The radius runs from 2 to 4 and the angle from 0 to π. Use \(dA=r\,dr\,d\theta\).')],r'\[\int_0^\pi\int_2^4 f(r\cos\theta,r\sin\theta)r\,dr\,d\theta.\]')
add(10,r'꼭짓점 \((-4,0),(0,4),(4,0)\)인 삼각형에서 \(\iint_R f\,dA\)를 반복적분으로 나타내라.',r'Write an iterated integral of \(f\) over the triangle with vertices \((-4,0),(0,4),(4,0)\).',[(r'높이 y에서 양 끝은 \(x=y-4\), \(x=4-y\)이고 \(0\le y\le4\)이다.',r'At height y the endpoints are \(x=y-4\) and \(x=4-y\), with \(0\le y\le4\).')],r'\[\int_0^4\int_{y-4}^{4-y} f(x,y)\,dx\,dy.\]')
add(11,r'원기둥좌표 \((2\sqrt3,\pi/3,2)\)를 직교좌표와 구면좌표로 바꾸어라.',r'Convert cylindrical \((2\sqrt3,\pi/3,2)\) to rectangular and spherical coordinates.',[(r'\(x=r\cos\theta=\sqrt3,y=r\sin\theta=3\).',r'\(x=r\cos\theta=\sqrt3,y=r\sin\theta=3\).'),(r'\(\rho=\sqrt{r^2+z^2}=4,\ \phi=\arccos(z/\rho)=\pi/3\).',r'\(\rho=\sqrt{r^2+z^2}=4,\ \phi=\arccos(z/\rho)=\pi/3\).')],r'\[(x,y,z)=(\sqrt3,3,2),\quad(\rho,\theta,\phi)=(4,\pi/3,\pi/3).\]')
add(12,r'직교좌표 \((2,2,-1)\)를 원기둥좌표와 구면좌표로 바꾸어라.',r'Convert \((2,2,-1)\) to cylindrical and spherical coordinates.',[(r'\(r=\sqrt{x^2+y^2}=2\sqrt2,\theta=\pi/4\).',r'\(r=\sqrt{x^2+y^2}=2\sqrt2,\theta=\pi/4\).'),(r'\(\rho=3\), 아래쪽 반공간이므로 \(\phi=\arccos(-1/3)>\pi/2\).',r'\(\rho=3\); the point is below the xy-plane, so \(\phi=\arccos(-1/3)>\pi/2\).')],r'\[(r,\theta,z)=(2\sqrt2,\pi/4,-1),\quad(\rho,\theta,\phi)=(3,\pi/4,\arccos(-1/3)).\]')
add(13,r'구면좌표 \((8,\pi/4,\pi/6)\)를 직교좌표와 원기둥좌표로 바꾸어라.',r'Convert spherical \((8,\pi/4,\pi/6)\) to rectangular and cylindrical coordinates.',[(r'\(r=\rho\sin\phi=4,\ z=\rho\cos\phi=4\sqrt3\).',r'\(r=\rho\sin\phi=4,\ z=\rho\cos\phi=4\sqrt3\).'),(r'\(x=r\cos\theta=2\sqrt2,y=r\sin\theta=2\sqrt2\).',r'\(x=r\cos\theta=2\sqrt2,y=r\sin\theta=2\sqrt2\).')],r'\[(x,y,z)=(2\sqrt2,2\sqrt2,4\sqrt3),\quad(r,\theta,z)=(4,\pi/4,4\sqrt3).\]')
add(14,r'(a) \(\theta=\pi/4\), (b) \(\phi=\pi/4\)의 곡면을 설명하라.',r'Identify the surfaces (a) \(\theta=\pi/4\), (b) \(\phi=\pi/4\).',[(r'(a) 방위각 고정이므로 \(y=x,x\ge0\)인 수직 반평면이다.',r'(a) A fixed azimuth gives the vertical half-plane \(y=x,x\ge0\).'),(r'(b) 양의 z축과 45°를 이루므로 \(z=\sqrt{x^2+y^2}\)인 위쪽 원뿔이다.',r'(b) The angle to the positive z-axis is 45°, giving the upper cone \(z=\sqrt{x^2+y^2}\).')],r'(a) \(y=x,\ x\ge0\); (b) \(z=\sqrt{x^2+y^2}\).',parts=['(a)','(b)'])
